-- Arbeitsrecht Berufsbildung > Rechte von Auszubildenden > Anspruch auf Ausbildungsvergütung (§ 17 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Hat ein Fachinformatiker-Anwärter auch während der Probezeit Anspruch auf Ausbildungsvergütung?', 2, '[{"text": "Ja", "correct": true, "because": "§ 17 BBiG gilt unabhängig von der Probezeit"}, {"text": "Nein", "correct": false, "because": "Vergütung ist immer Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbildungsunternehmen die Vergütung eines Fachinformatikers einbehalten, wenn er die Berufsschule nicht besucht?', 2, '[{"text": "Nein", "correct": true, "because": "§ 17 BBiG garantiert die Vergütung unabhängig davon"}, {"text": "Ja", "correct": false, "because": "Vergütung darf nicht willkürlich gekürzt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Ausbildungsvergütung für einen Fachinformatiker monatlich ausgezahlt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Das ist die übliche Praxis nach § 17 BBiG"}, {"text": "Nein", "correct": false, "because": "Monatliche Zahlung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker auf seinen Vergütungsanspruch verzichten, um dem Betrieb zu helfen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 17 BBiG ist zwingendes Recht"}, {"text": "Ja", "correct": false, "because": "Der Anspruch ist nicht verhandelbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf die Vergütung eines Fachinformatikers während der IHK-Prüfungsvorbereitung gekürzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "§ 17 BBiG schützt den vollen Anspruch"}, {"text": "Ja", "correct": false, "because": "Kürzungen sind nicht erlaubt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage sichert einem Fachinformatiker die Ausbildungsvergütung zu?', 2, '[{"text": "§ 17 BBiG", "correct": true, "because": "Regelt den Vergütungsanspruch"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Ausbildungspflichten"}, {"text": "§ 22 BBiG", "correct": false, "because": "Regelt Kündigungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Ausbildungsunternehmen die Vergütung eines Fachinformatikers nicht zahlt?', 3, '[{"text": "Der Auszubildende kann sie einklagen", "correct": true, "because": "§ 17 BBiG ist einklagbar"}, {"text": "Der Anspruch verfällt automatisch", "correct": false, "because": "Der Anspruch bleibt bestehen"}, {"text": "Die IHK übernimmt die Zahlung", "correct": false, "because": "Das ist nicht deren Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor bestimmt die Höhe der Ausbildungsvergütung eines Fachinformatikers?', 3, '[{"text": "Tarifverträge oder betriebliche Vereinbarungen", "correct": true, "because": "§ 17 BBiG verweist darauf"}, {"text": "Die Anzahl der Berufsschultage", "correct": false, "because": "Irrelevant für die Höhe"}, {"text": "Die Note in der IHK-Prüfung", "correct": false, "because": "Hat keinen Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, die Ausbildungsvergütung für einen Fachinformatiker zu zahlen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 17 BBiG legt das fest"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule zahlt nicht"}, {"text": "Die IHK", "correct": false, "because": "IHK ist nur organisatorisch tätig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn seine Vergütung zu niedrig ist?', 3, '[{"text": "Den Betrieb auf § 17 BBiG und Tarifverträge hinweisen", "correct": true, "because": "Das ist der rechtliche Weg"}, {"text": "Sofort kündigen", "correct": false, "because": "Zu radikal ohne Klärung"}, {"text": "Die Berufsschule informieren", "correct": false, "because": "Schule hat keine Befugnis"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind Teil des Vergütungsanspruchs eines Fachinformatikers nach § 17 BBiG?', 4, '[{"text": "Grundvergütung", "correct": true, "because": "Kernbestandteil"}, {"text": "Zuschläge für Überstunden", "correct": true, "because": "Falls tariflich geregelt"}, {"text": "Kosten für Arbeitskleidung", "correct": false, "because": "Das ist kein Vergütungsbestandteil"}, {"text": "Weihnachtsgeld", "correct": true, "because": "Wenn tariflich vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen muss ein Fachinformatiker erfüllen, um Vergütung nach § 17 BBiG zu erhalten?', 3, '[{"text": "Im Ausbildungsverhältnis stehen", "correct": true, "because": "Grundvoraussetzung"}, {"text": "Berufsschule besuchen", "correct": false, "because": "Nicht Bedingung für Vergütung"}, {"text": "IHK-Prüfung bestehen", "correct": false, "because": "Erst am Ende relevant"}, {"text": "Vertrag unterschreiben", "correct": true, "because": "Rechtliche Basis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der die Vergütung eines Fachinformatikers nicht zahlt?', 4, '[{"text": "Schadensersatzforderungen", "correct": true, "because": "Verletzung von § 17 BBiG"}, {"text": "Zwangsvollstreckung", "correct": true, "because": "Bei Klage möglich"}, {"text": "Automatische Kündigung", "correct": false, "because": "Vertrag bleibt bestehen"}, {"text": "Bußgelder durch die IHK", "correct": false, "because": "IHK hat keine Strafbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können die Höhe der Ausbildungsvergütung eines Fachinformatikers beeinflussen?', 3, '[{"text": "Branchentarifverträge", "correct": true, "because": "Häufig in der IT-Branche"}, {"text": "Betriebsgröße", "correct": true, "because": "Kann Vergütung variieren"}, {"text": "Programmierkenntnisse", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "Region", "correct": true, "because": "Regionale Unterschiede existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört nicht zur Ausbildungsvergütung eines Fachinformatikers?', 2, '[{"text": "Monatliches Gehalt", "correct": false, "because": "Ist Teil davon"}, {"text": "Urlaubsgeld", "correct": false, "because": "Kann enthalten sein"}, {"text": "Kosten für Arbeitsmittel", "correct": true, "because": "Separat vom Betrieb zu stellen"}, {"text": "Zuschlag für Nachtarbeit", "correct": false, "because": "Kann tariflich geregelt sein"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Vergütung eines Fachinformatikers muss immer gleich hoch sein. b) § 17 BBiG schützt den Anspruch.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Höhe variiert nach Tarif"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "§ 17 BBiG ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Fachinformatiker hat auch bei Krankheit Anspruch auf Vergütung. b) Der Betrieb kann die Vergütung bei Streik kürzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Krankheit schützt § 17 BBiG, Streik nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Vergütung eines Fachinformatikers steigt mit jedem Ausbildungsjahr. b) Ohne Tarifvertrag gibt es keine Vergütung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Steigerung ist üblich, b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker hat keinen Vergütungsanspruch bei Kündigung. b) § 17 BBiG gilt nur für Vollzeit-Auszubildende.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Anspruch bleibt bis Kündigung"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "Gilt auch für Teilzeit"}, {"text": "Beides falsch", "correct": true, "because": "Anspruch bleibt, § 17 BBiG gilt allgemein"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Vergütung eines Fachinformatikers kann in Naturalien gezahlt werden. b) Der Anspruch besteht nur bei bestandener Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Naturalien sind nicht üblich"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "Anspruch gilt sofort"}, {"text": "Beides falsch", "correct": true, "because": "Geldzahlung ist Standard, Anspruch gilt von Anfang an"}]');

